import RNA
target = "((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..))."
n=len(target)

# complementary seed: G-C pairs, A unpaired - this is the fold-test baseline
pair={}; stack=[]
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pair[j]=i; pair[i]=j

def build(seqmod):
    seq=['A']*n
    for i in range(n):
        if i in pair:
            j=pair[i]
            if i<j:
                seq[i],seq[j]=seqmod(i,j)
    return ''.join(seq)

def score(seq):
    fc=RNA.fold_compound(seq)
    mfe,energy=fc.mfe()
    bp=RNA.bp_distance(mfe,target)
    return bp,mfe

# baseline: all G-C
